package com.metaarch.catalog.product;
import java.time.Instant; import java.util.*; import com.metaarch.catalog.image.ProductImageResponse; import com.metaarch.catalog.variant.ProductVariantResponse;
public record ProductResponse(UUID id,UUID categoryId,String categoryName,String subcategory,String name,String slug,String sku,String description,String brand,String ingredients,String specifications,String pack,String type,String shelfLife,String tags,String highlights,String aboutSource,ProductStatus status,boolean featured,boolean special,boolean newArrival,boolean bestSeller,boolean globalProduct,String fulfillmentType,String deliveryMethod,List<ProductVariantResponse> variants,List<ProductImageResponse> images,Instant createdAt,Instant updatedAt,String ownerLocation,Boolean locationAvailable) {
 public static ProductResponse from(Product v){return from(v,null);}
 public static ProductResponse from(Product v,Boolean locationAvailable){return new ProductResponse(v.getId(),v.getCategory().getId(),v.getCategory().getName(),v.getSubcategory(),v.getName(),v.getSlug(),v.getSku(),v.getDescription(),v.getBrand(),v.getIngredients(),v.getSpecifications(),v.getPack(),v.getType(),v.getShelfLife(),v.getTags(),v.getHighlights(),v.getAboutSource(),v.getStatus(),v.isFeatured(),v.isSpecial(),v.isNewArrival(),v.isBestSeller(),v.isGlobalProduct(),v.getFulfillmentType(),v.getDeliveryMethod(),v.getVariants().stream().map(ProductVariantResponse::from).toList(),v.getImages().stream().map(ProductImageResponse::from).toList(),v.getCreatedAt(),v.getUpdatedAt(),v.getOwnerLocation(),locationAvailable);}
}
